css:
.dialog {
  display: flex;
  flex-direction: column;
  height: 300px;
  max-width: 420px;
  border: 1px solid #a1a1aa;
  border-radius: 8px;
  background: #fafafa;
  overflow: hidden;
}

.head,
.foot {
  flex: 0 0 auto;
  padding: 12px 16px;
  background: #18181b;
  color: #fafafa;
}

.body {
  flex: 1;
  min-height: 0; /* let the body shrink below its content */
  overflow-y: auto;
  padding: 12px 16px;
}

.body p {
  margin: 0 0 10px;
}

.foot {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.btn {
  padding: 6px 12px;
  border: 1px solid #a1a1aa;
  border-radius: 4px;
  background: #fff;
}

.primary {
  border-color: #f97316;
  background: #f97316;
  color: #fff;
}
